def main():
    src=open(os.path.join(ROOT,'index.html'),encoding='utf-8').read()
    nav=''.join('<a href="/%s/">%s</a>'%(s,html.escape(h1)) for s,a,h1,t,d,x in P)
    nav='<a href="/">TAP APP</a>'+nav
    assert src.count('<!--SEO-->')==1
    base,n=re.subn(r'<!--NAV-->.*?<!--/NAV-->',lambda m:'<!--NAV-->'+nav+'<!--/NAV-->',src,flags=re.S)
    assert n==1
    if base!=src: open(os.path.join(ROOT,'index.html'),'w',encoding='utf-8').write(base)
    src=base
    for slug,app,h1,title,desc,text in P:
        full=title+' | TAP APP'
        s=src
        def sub(pat,rep,flags=0,cnt=1):
            nonlocal s
            s2,n=re.subn(pat,lambda m:rep,s,count=cnt,flags=flags)
            assert n==1,pat; s=s2
        url='%s/%s/'%(SITE,slug)
        sub(r'<title>.*?</title>','<title>%s</title>'%html.escape(full))
        sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="%s">'%html.escape(desc,True))
        sub(r'<link rel="canonical" href="[^"]*">','<link rel="canonical" href="%s">'%url)
        sub(r'<meta property="og:title" content="[^"]*">','<meta property="og:title" content="%s">'%html.escape(full,True))
        sub(r'<meta property="og:description" content="[^"]*">','<meta property="og:description" content="%s">'%html.escape(desc,True))
        sub(r'<meta property="og:url" content="[^"]*">','<meta property="og:url" content="%s">'%url)
        ld={"@context":"https://schema.org","@type":"WebApplication","name":title.split(' — ')[0],"url":url,"description":desc,"applicationCategory":"UtilitiesApplication","operatingSystem":"Any","inLanguage":"ru","offers":{"@type":"Offer","price":"0","priceCurrency":"RUB"},"isPartOf":{"@type":"WebSite","name":"TAP APP","url":SITE+"/"}}
        head='<script>window.__START_APP=%s;</script>\n<script type="application/ld+json">%s</script>\n'%(json.dumps(app),json.dumps(ld,ensure_ascii=False).replace('</','<\\/'))
        sub(r'<meta name="yandex-verification"',head+'<meta name="yandex-verification"')
        seo='<section class="seo"><h2>%s</h2><p>%s</p></section>'%(html.escape(title.split(' — ')[0]),html.escape(text))
        sub(r'<!--SEO-->',seo)
        sub(r'<h1 class="title" id="title">[^<]*</h1>','<h1 class="title" id="title">%s</h1>'%h1)
        os.makedirs(os.path.join(ROOT,slug),exist_ok=True)
        open(os.path.join(ROOT,slug,'index.html'),'w',encoding='utf-8').write(s)
    # sitemap
    sm='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n  <url><loc>%s/</loc><changefreq>weekly</changefreq><priority>1.0</priority></url>\n'%SITE
    for slug,*_ in P: sm+='  <url><loc>%s/%s/</loc><changefreq>monthly</changefreq><priority>0.8</priority></url>\n'%(SITE,slug)
    open(os.path.join(ROOT,'sitemap.xml'),'w',encoding='utf-8').write(sm+'</urlset>\n')
    open(os.path.join(ROOT,'robots.txt'),'w').write('User-agent: *\nAllow: /\nSitemap: %s/sitemap.xml\n'%SITE)
    print('pages',len(P))
main()
